// Source of truth: this .ts file. state.js is generated by `npm --prefix web run build:ts`.
import "./ready.js"; // every screen imports this module, so it carries the first-paint signal
// Scenario state lives in the query string, so a URL reproduces the screen.
// Keys: site, start (ISO UTC), hours, layer (answer|why|proof), task (explore|class|plan),
// lang, night, blackout, battery (assumed limits, editable by the user).
export type Layer = "answer" | "why" | "proof";
export type Task = "explore" | "class" | "plan";
/** Assumed limits declared by the user. */
export interface Rules { night: number; blackout: number; battery: number; }
export interface ScenarioState extends Rules {
  site: string | null; start: string | null; hours: number | null; layer: Layer; task: Task | null; lang: string | null;
  /** Reproducible link, when a screen sets one. */
  link?: string | null;
}
type Listener = (state: ScenarioState) => void;

export const LAYERS: Layer[] = ["answer", "why", "proof"];
export const TASKS: Record<Task, Layer> = { explore: "answer", class: "why", plan: "proof" };
// Assumed limits declared by the user; these are only editable defaults (contract rule 5).
export const DEFAULT_RULES: Readonly<Rules> = Object.freeze({ night: 60, blackout: 72, battery: 30 });
const NUM = ["hours", "night", "blackout", "battery"] as const;

export function parseState(search: string = globalThis.location?.search || ""): ScenarioState {
  const q = new URLSearchParams(search);
  const s: Omit<ScenarioState, "layer" | "task"> & { layer: Layer | null; task: string | null } = { site: q.get("site") || null, start: q.get("start") || null, hours: null,
    layer: null, task: q.get("task") || null, lang: q.get("lang") || null, ...DEFAULT_RULES };
  for (const k of NUM) if (q.has(k)) { const v = Number(q.get(k)); if (Number.isFinite(v) && v > 0) s[k] = v; }
  if (s.start && Number.isNaN(Date.parse(s.start))) s.start = null;
  // AUD-15: series are hourly; a fractional window or a start off the hour would count samples that do not
  // match the declared duration. Accept whole hours only, and start on the hour (UTC), like the Go API grid.
  if (s.hours != null && !Number.isInteger(s.hours)) s.hours = null;
  if (s.start && Date.parse(s.start) % 3600000 !== 0) s.start = null;
  if (!((s.task as string) in TASKS)) s.task = null; // `null in TASKS` coerces to "null": false
  const l = q.get("layer");
  s.layer = (LAYERS as string[]).includes(l as string) ? (l as Layer) : (s.task ? TASKS[s.task as Task] : "answer");
  return s as ScenarioState;
}

export function toQuery(state: Partial<ScenarioState>): string {
  const q = new URLSearchParams();
  for (const k of ["site", "start", "hours", "layer", "task", "lang"] as const) if (state[k] != null) q.set(k, String(state[k]));
  for (const k of Object.keys(DEFAULT_RULES) as (keyof Rules)[]) if (state[k] != null && state[k] !== DEFAULT_RULES[k]) q.set(k, String(state[k]));
  return q.toString();
}

let listeners: Listener[] = [];
let cur: ScenarioState | null = null;
export function getState(): ScenarioState { return cur || (cur = parseState()); }
/** Merge a patch, write it to the URL (replaceState, no reload) and notify listeners. */
export function setState(patch: Partial<ScenarioState>): ScenarioState {
  cur = { ...getState(), ...patch };
  if (globalThis.history) history.replaceState(null, "", "?" + toQuery(cur) + location.hash);
  for (const fn of listeners) fn(cur);
  return cur;
}
export function onState(fn: Listener): () => void { listeners.push(fn); return () => { listeners = listeners.filter(f => f !== fn); }; }
/** Link to another screen carrying the current scenario. */
export function hrefTo(page: string, state: Partial<ScenarioState> = getState()): string { const q = toQuery(state); return page + (q ? "?" + q : ""); }
